-- Migration 430: AA-1003 R6 (S282) — the thresholds of the partner and agency reports in the platform settings registry
-- (CIS 407; tech lead S279: a threshold, limit, cap or policy value is a setting on Platform › Settings, never a code
-- literal or an env var alone).
--
-- Why. Slice R6 of the report catalog renders EX-03 (partner growth and churn, monthly) and EX-07 (partner onboarding
-- funnel, weekly) with the CIS report engine (services/reports/partners.py). Their KPI definitions in the registry
-- (docs/reports/kpis.yaml) carry decision levels: K-PART-ACT counts a tenant as activated with a first publish "within
-- 14 days", K-ONB-STUCK lists partners "more than 7 days" on one step, K-PART-QUOTA flags an upsell candidate above
-- 80 % of its quota and a churn risk under 10 % for 2 months. Those five numbers become settings here, so an
-- administrator changes them on Platform › Settings (audited) and the reports read the value in force.
--
-- What:
--   1. Five rows in shared.setting_definition (seed block below, read by scripts/settings/gen_compiled_defaults.py into
--      shared/settings/compiled_defaults.json in this PR), area "reports", scope platform, impact low, single approval,
--      no evidence, no env override, enforced (services/reports/settings_keys.py names every key in this PR, the
--      settings-lint reader check; the code PR reads them through shared.settings):
--        cis.reports.partner_activation_days    int days 1-90, default 14 (K-PART-ACT)
--        cis.reports.partner_stuck_days         int days 1-60, default 7 (K-ONB-STUCK)
--        cis.reports.partner_upsell_quota_pct   pct 1-100, default 80 (K-PART-QUOTA upsell)
--        cis.reports.partner_low_use_quota_pct  pct 0-100, default 10 (K-PART-QUOTA churn risk)
--        cis.reports.partner_low_use_months     int months 1-12, default 2 (K-PART-QUOTA churn risk)
--      Each seed row carries its plain label and its EN + VI operator guide (CIS 416 rule).
--   2. Register 430.
--
-- Behaviour on apply. None for running code: no value row is seeded and nothing on main reads these keys; after the code
-- PR the reports read the defaults (the levels the registry text names today) until an administrator changes a value.
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): config rows INSERTed into an existing table.
-- MIG-4: a migration-only PR, applied on Dev by Infra Migration Apply when the job tables are idle (ADR 0017a), then the
-- code PR (no readiness raise: a reader falls back to the compiled defaults). DM-6.1: no personal data. DM-7.1: no new
-- table.
--
-- Number. 429 is the newest CIS migration on main (16/11/2026). If the owner main max + 1 differs at merge, renumber
-- (git grep '430_' and '430' here, in tests/integration/test_aa1003_migration_430.py, compiled_defaults.json and the
-- implementation notes docs/implementation-notes/AA-1003.md).
--
-- Locks. One INSERT of five rows (the definition guard trigger allows the file's role, cis_owner). lock_timeout 5s.
-- Idempotent (ON CONFLICT (key) DO NOTHING), one transaction, self-registering.
--
-- Rollback (a new forward migration, after the code PR is reverted): DELETE the keys' value rows first, then the keys.

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-seed:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted seed)
INSERT INTO shared.setting_definition
    (key, app, area, label, description, value_type, unit, min_value, max_value, allowed_values, default_value,
     scope_kind, impact, approval, evidence_required, env_override, cache_s, enforced, guide)
SELECT s.key, s.app, s.area, s.label, s.description, s.value_type, s.unit, s.min_value, s.max_value, s.allowed_values,
       s.default_value, s.scope_kind, s.impact, s.approval, s.evidence_required, s.env_override, s.cache_s, s.enforced,
       s.guide
  FROM jsonb_to_recordset($seed$
[
{"key": "cis.reports.partner_activation_days", "app": "cis", "area": "reports", "label": "Partner reports: days to count a new tenant as activated", "description": "Reports EX-03 and EX-07 (AA-1003 R6): a Content studio tenant counts as activated (K-PART-ACT) when its first piece is published within this many days of the tenant's creation. Read by services/reports/partners.py when the report is generated; no other code reads it.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 90, "allowed_values": null, "default_value": 14, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days a new Content studio tenant has to publish its first piece and still count as activated in the partner reports (activation rate in the monthly partner growth report and the weekly onboarding funnel).", "raise": "More tenants count as activated, and the rate says less about how fast new tenants get value.", "lower": "Fewer tenants count as activated; the rate shows a slow start sooner.", "when": "Change it when the onboarding plan promises a first publish in another time, or when the business owner wants a stricter measure.", "example": "With the default of 14 days, a tenant created on 1 March that publishes on 10 March is activated; one that publishes on 20 March is not."}, "vi": {"what": "Một tenant Content studio mới có bao nhiêu ngày để đăng bài đầu tiên mà vẫn được tính là đã kích hoạt trong các báo cáo đối tác (tỉ lệ kích hoạt trong báo cáo tăng trưởng đối tác hằng tháng và phễu kích hoạt hằng tuần).", "raise": "Nhiều tenant được tính là đã kích hoạt hơn, và tỉ lệ nói ít hơn về việc tenant mới nhận giá trị nhanh tới đâu.", "lower": "Ít tenant được tính là đã kích hoạt hơn; tỉ lệ cho thấy việc khởi động chậm sớm hơn.", "when": "Đổi khi kế hoạch onboarding hứa bài đăng đầu tiên trong một khoảng thời gian khác, hoặc khi chủ doanh nghiệp muốn thước đo chặt hơn.", "example": "Với mặc định 14 ngày, tenant tạo ngày 1/3 đăng bài ngày 10/3 là đã kích hoạt; tenant đăng ngày 20/3 thì chưa."}}},
{"key": "cis.reports.partner_stuck_days", "app": "cis", "area": "reports", "label": "Partner reports: days on one onboarding step before a partner is stuck", "description": "Report EX-07 (AA-1003 R6): a partner that is not activated yet and has spent more than this many days on one onboarding step (Content studio: created, first member, brand brief, first approved piece; CRM: agency created without an active owner) is listed as stuck (K-ONB-STUCK). Read by services/reports/partners.py when the report is generated.", "value_type": "int", "unit": "days", "min_value": 1, "max_value": 60, "allowed_values": null, "default_value": 7, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many days a new partner may stay on one onboarding step before the weekly onboarding funnel lists it as stuck, so someone calls it.", "raise": "Fewer partners are listed as stuck, and a slow partner is noticed later.", "lower": "More partners are listed as stuck, and the list may include partners that are simply busy.", "when": "Lower it when there are few new partners and each one gets a personal call; raise it when the stuck list grows faster than the team can call.", "example": "With the default of 7 days, a tenant that uploaded its brand brief 9 days ago and has no approved piece yet is listed as stuck."}, "vi": {"what": "Một đối tác mới được ở bao nhiêu ngày trên một bước onboarding trước khi phễu kích hoạt hằng tuần đưa nó vào danh sách bị kẹt, để có người gọi hỗ trợ.", "raise": "Ít đối tác bị liệt kê là kẹt hơn, và đối tác chậm được phát hiện muộn hơn.", "lower": "Nhiều đối tác bị liệt kê là kẹt hơn, và danh sách có thể gồm cả đối tác chỉ đơn giản là đang bận.", "when": "Giảm khi có ít đối tác mới và mỗi đối tác được gọi riêng; tăng khi danh sách kẹt tăng nhanh hơn khả năng gọi của nhóm.", "example": "Với mặc định 7 ngày, tenant đã tải brand brief 9 ngày trước mà chưa có bài nào được duyệt sẽ nằm trong danh sách kẹt."}}},
{"key": "cis.reports.partner_upsell_quota_pct", "app": "cis", "area": "reports", "label": "Partner reports: quota use that makes an upsell candidate", "description": "Report EX-03 (AA-1003 R6, K-PART-QUOTA): a partner whose monthly quota use (Content studio tours or API calls, CRM seats) is at or above this percent of its own plan quota is listed as an upsell candidate. Read by services/reports/partners.py when the report is generated.", "value_type": "pct", "unit": "%", "min_value": 1, "max_value": 100, "allowed_values": null, "default_value": 80, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The share of its own plan quota a partner must use in a month before the partner growth report lists it as an upsell candidate (a bigger plan may suit it).", "raise": "Only partners close to their limit are listed; fewer upsell calls, and some partners hit their limit before anyone calls.", "lower": "More partners are listed as upsell candidates, including some that still have room in their plan.", "when": "Change it when the sales approach changes, for example to call partners earlier before a busy season.", "example": "With the default of 80 %, a tenant that rewrote 85 tours on a 100-tour quota this month is an upsell candidate."}, "vi": {"what": "Tỉ lệ hạn mức gói của chính mình mà một đối tác phải dùng trong tháng trước khi báo cáo tăng trưởng đối tác đưa nó vào danh sách ứng viên nâng gói (gói lớn hơn có thể hợp hơn).", "raise": "Chỉ đối tác sát giới hạn mới được liệt kê; ít cuộc gọi nâng gói hơn, và vài đối tác chạm giới hạn trước khi có ai gọi.", "lower": "Nhiều đối tác được liệt kê là ứng viên nâng gói hơn, kể cả đối tác còn dư hạn mức.", "when": "Đổi khi cách bán hàng thay đổi, ví dụ muốn gọi đối tác sớm hơn trước mùa cao điểm.", "example": "Với mặc định 80 %, tenant viết lại 85 tour trên hạn mức 100 tour trong tháng là ứng viên nâng gói."}}},
{"key": "cis.reports.partner_low_use_quota_pct", "app": "cis", "area": "reports", "label": "Partner reports: quota use below which a partner is at risk", "description": "Report EX-03 (AA-1003 R6, K-PART-QUOTA): a partner with a live subscription whose quota use stays below this percent of its own plan quota for the number of months in cis.reports.partner_low_use_months is listed as a churn risk. Read by services/reports/partners.py when the report is generated.", "value_type": "pct", "unit": "%", "min_value": 0, "max_value": 100, "allowed_values": null, "default_value": 10, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "The share of its own plan quota under which a paying partner is listed as a churn risk in the partner growth report, when it stays that low for the months set in the low-use months setting.", "raise": "More partners are listed as churn risks, including some that are simply in a quiet month.", "lower": "Only partners that barely use the product are listed; fewer rescue calls.", "when": "Raise it before a renewal round to call more partners; lower it when the list is mostly seasonal partners.", "example": "With the default of 10 % and 2 months, a tenant that rewrote 5 and 3 tours on a 100-tour quota in the last two months is a churn risk."}, "vi": {"what": "Tỉ lệ hạn mức gói của chính mình mà dưới mức đó một đối tác trả tiền bị liệt kê là có nguy cơ rời bỏ trong báo cáo tăng trưởng đối tác, khi nó giữ mức thấp đó trong số tháng đặt ở thiết lập số tháng dùng ít.", "raise": "Nhiều đối tác bị liệt kê là có nguy cơ rời bỏ hơn, kể cả đối tác chỉ đang vào tháng vắng.", "lower": "Chỉ đối tác gần như không dùng sản phẩm mới bị liệt kê; ít cuộc gọi giữ chân hơn.", "when": "Tăng trước đợt gia hạn để gọi nhiều đối tác hơn; giảm khi danh sách chủ yếu là đối tác theo mùa.", "example": "Với mặc định 10 % và 2 tháng, tenant viết lại 5 rồi 3 tour trên hạn mức 100 tour trong hai tháng gần nhất là có nguy cơ rời bỏ."}}},
{"key": "cis.reports.partner_low_use_months", "app": "cis", "area": "reports", "label": "Partner reports: months of low use before a churn-risk flag", "description": "Report EX-03 (AA-1003 R6, K-PART-QUOTA): how many consecutive months, ending with the report's month, a partner's quota use must stay below cis.reports.partner_low_use_quota_pct before it is listed as a churn risk. Read by services/reports/partners.py when the report is generated.", "value_type": "int", "unit": "months", "min_value": 1, "max_value": 12, "allowed_values": null, "default_value": 2, "scope_kind": "platform", "impact": "low", "approval": "single", "evidence_required": false, "env_override": null, "cache_s": 60, "enforced": true, "guide": {"en": {"what": "How many months in a row, ending with the month of the report, a paying partner must stay under the low-use share before the partner growth report lists it as a churn risk.", "raise": "A partner must stay quiet for longer before it is listed; fewer false alarms, later rescue calls.", "lower": "A single quiet month is enough to be listed; earlier rescue calls, more false alarms.", "when": "Lower it when partners leave soon after a quiet spell; raise it when many partners are seasonal.", "example": "With the default of 2 months, a tenant under the low-use share in September and October is listed in the October report."}, "vi": {"what": "Bao nhiêu tháng liên tiếp, tính đến tháng của báo cáo, một đối tác trả tiền phải ở dưới tỉ lệ dùng ít trước khi báo cáo tăng trưởng đối tác liệt kê nó là có nguy cơ rời bỏ.", "raise": "Đối tác phải im lặng lâu hơn mới bị liệt kê; ít báo động nhầm hơn, gọi giữ chân muộn hơn.", "lower": "Một tháng vắng là đủ để bị liệt kê; gọi giữ chân sớm hơn, nhiều báo động nhầm hơn.", "when": "Giảm khi đối tác hay rời bỏ ngay sau một giai đoạn vắng; tăng khi nhiều đối tác theo mùa.", "example": "Với mặc định 2 tháng, tenant ở dưới tỉ lệ dùng ít trong tháng 9 và tháng 10 sẽ nằm trong báo cáo tháng 10."}}}
]
$seed$::jsonb) AS s (key text, app text, area text, label text, description text, value_type text, unit text,
                      min_value numeric, max_value numeric, allowed_values jsonb, default_value jsonb, scope_kind text,
                      impact text, approval text, evidence_required boolean, env_override text, cache_s integer,
                      enforced boolean, guide jsonb)
ON CONFLICT (key) DO NOTHING;
-- settings-seed:end

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('430', now(), 'AA-1003 R6: the partner report thresholds in the settings registry (cis.reports.partner_*)')
ON CONFLICT (version) DO NOTHING;

COMMIT;
